/* GardenSync Almanac edition - plant library (Zone 6a) */
const PLANTS = [{"id":"tomato","name":"Tomato","emoji":"🍅","type":"vegetable","spacing":24,"daysToHarvest":75,"waterNeed":"medium","sunNeed":"full","sowIndoors":-6,"transplantAfterFrost":2,"directSow":null,"harvestWeeks":10,"companions":["basil","marigold","carrot","parsley","onion","garlic","chive","nasturtium","lettuce","spinach","borage"],"enemies":["cabbage","fennel","dill","potato","broccoli","kale"],"notes":"Stake or cage. Indeterminate types produce all season.","seedStart":"Start seeds indoors 6-8 weeks before last frost (Mar 1-7). Use seed starting mix, 1/4\" deep. Keep at 70-80°F. Transplant out after May 1 when soil is 60°F+.","care":"Water deeply 1-2x/week. Mulch heavily. Remove suckers for determinate types. Side-dress with compost mid-season.","lowMaintenance":true},{"id":"cucumber","name":"Cucumber","emoji":"🥒","type":"vegetable","spacing":18,"daysToHarvest":60,"waterNeed":"high","sunNeed":"full","sowIndoors":-3,"transplantAfterFrost":2,"directSow":2,"harvestWeeks":8,"companions":["green-beans","peas","lettuce","sunflower","radish","dill","marigold","nasturtium","corn","borage"],"enemies":["potato","sage","cantaloupe","rosemary"],"notes":"Can trellis vertically to save space. Pick frequently.","seedStart":"Start indoors 3-4 weeks before last frost (Mar 21-28) OR direct sow after May 1. Plant 1\" deep. Needs 70°F soil.","care":"Needs consistent moisture. Trellis to save space & improve air flow. Pick daily once producing.","lowMaintenance":false},{"id":"lettuce","name":"Lettuce","emoji":"🥬","type":"vegetable","spacing":8,"daysToHarvest":45,"waterNeed":"medium","sunNeed":"partial","sowIndoors":-4,"transplantAfterFrost":-2,"directSow":-2,"harvestWeeks":6,"companions":["carrot","radish","strawberry","chive","onion","garlic","green-beans","peas","spinach","dill"],"enemies":[],"notes":"Cool season crop. Succession plant every 2 weeks. Bolts in heat.","seedStart":"Start indoors mid-March or direct sow as early as April 1. Surface sow (needs light). Succession plant every 2 weeks through May, resume in Aug.","care":"Keep soil consistently moist. Shade cloth in summer. Harvest outer leaves for continuous production.","lowMaintenance":true},{"id":"spinach","name":"Spinach","emoji":"🍃","type":"vegetable","spacing":6,"daysToHarvest":40,"waterNeed":"medium","sunNeed":"partial","sowIndoors":null,"transplantAfterFrost":null,"directSow":-4,"harvestWeeks":4,"companions":["strawberry","peas","green-beans","lettuce","radish","kale"],"enemies":["potato"],"notes":"Very cold-hardy. One of the first crops to plant. Bolts fast in heat.","seedStart":"Direct sow 4-6 weeks before last frost (Mar 7-21). Plant 1/2\" deep, 1\" apart, thin to 6\". Can also fall sow in September.","care":"Keep cool & moist. Mulch to retain moisture. Harvest outer leaves. Plant again in fall.","lowMaintenance":true},{"id":"green-beans","name":"Green Beans","emoji":"🫘","type":"vegetable","spacing":6,"daysToHarvest":55,"waterNeed":"low","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":1,"harvestWeeks":6,"companions":["corn","zucchini","cucumber","strawberry","marigold","radish","nasturtium","carrot","lettuce","eggplant","potato","borage"],"enemies":["onion","garlic","fennel","chive"],"notes":"Nitrogen fixer. Bush types need no support. Very productive.","seedStart":"Direct sow 1 week after last frost (Apr 25-May 1). Plant 1\" deep, 6\" apart. Soil must be 60°F+. Do NOT start indoors — beans hate transplanting.","care":"Minimal care once established. Water during drought only. Pick regularly to encourage production. Bush types are lowest maintenance.","lowMaintenance":true},{"id":"pepper","name":"Bell Pepper","emoji":"🌶","type":"vegetable","spacing":18,"daysToHarvest":70,"waterNeed":"medium","sunNeed":"full","sowIndoors":-8,"transplantAfterFrost":2,"directSow":null,"harvestWeeks":10,"companions":["tomato","basil","carrot","marigold","onion","garlic","oregano","parsley","spinach","lettuce"],"enemies":["fennel","kohlrabi"],"notes":"Slow to start. Needs warm soil. Very productive once going.","seedStart":"Start indoors 8-10 weeks before last frost (Feb 15-Mar 1). Needs warmth (75-85°F) for germination. Slow grower. Harden off carefully. Transplant after May 1.","care":"Mulch well. Stake if heavy with fruit. Water consistently. Pick green or let ripen to red for more sweetness.","lowMaintenance":true},{"id":"zucchini","name":"Zucchini","emoji":"🥜","type":"vegetable","spacing":24,"daysToHarvest":50,"waterNeed":"medium","sunNeed":"full","sowIndoors":-3,"transplantAfterFrost":1,"directSow":1,"harvestWeeks":10,"companions":["corn","green-beans","marigold","nasturtium","dill","radish","sunflower","borage"],"enemies":["potato"],"notes":"Incredibly productive. One plant feeds many. Pick small.","seedStart":"Start indoors 3-4 weeks before last frost (Mar 28) or direct sow 1 week after (Apr 25). Plant 1\" deep. Germinates fast in warm soil.","care":"Water at base to prevent powdery mildew. Harvest at 6-8\" for best flavor. Check daily — they grow FAST.","lowMaintenance":true},{"id":"radish","name":"Radish","emoji":"💮","type":"vegetable","spacing":3,"daysToHarvest":25,"waterNeed":"low","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":-4,"harvestWeeks":2,"companions":["lettuce","peas","green-beans","carrot","cucumber","spinach","nasturtium","zucchini"],"enemies":[],"notes":"Fastest veggie! Great row marker. Succession plant biweekly.","seedStart":"Direct sow 4-6 weeks before last frost (Mar 7-21). Plant 1/2\" deep, 1\" apart. Succession sow every 2 weeks. Also great fall crop (Sept).","care":"Virtually zero maintenance. Thin to 2-3\" apart. Harvest promptly or they get pithy. Great teaching crop for new gardeners.","lowMaintenance":true},{"id":"carrot","name":"Carrot","emoji":"🥕","type":"vegetable","spacing":3,"daysToHarvest":70,"waterNeed":"low","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":-2,"harvestWeeks":8,"companions":["tomato","lettuce","onion","rosemary","radish","peas","green-beans","chive","garlic"],"enemies":["dill"],"notes":"Direct sow only — doesn't transplant. Loose soil essential.","seedStart":"Direct sow 2-3 weeks before last frost (Apr 1). Tiny seeds — mix with sand for even sowing. Press into soil surface, barely cover. Keep moist until germination (14-21 days).","care":"Thin to 2-3\" apart when 2\" tall. Keep soil loose and stone-free. Mulch shoulders to prevent greening. Sweet after frost!","lowMaintenance":true},{"id":"kale","name":"Kale","emoji":"🥬","type":"vegetable","spacing":18,"daysToHarvest":55,"waterNeed":"low","sunNeed":"full","sowIndoors":-6,"transplantAfterFrost":-2,"directSow":-4,"harvestWeeks":20,"companions":["green-beans","beet","lettuce","onion","garlic","dill","nasturtium","marigold","spinach"],"enemies":["strawberry","tomato"],"notes":"Cold-hardy champion. Sweetens after frost. Harvest all season.","seedStart":"Start indoors 6 weeks before last frost (Mar 7) or direct sow 4 weeks before (Mar 21). Plant 1/4\" deep. Cold tolerant — can go out early.","care":"Extremely low maintenance. Harvest lower leaves, plant keeps producing. Gets SWEETER after frost. Can overwinter in Zone 6a with mulch.","lowMaintenance":true},{"id":"onion","name":"Onion","emoji":"🧅","type":"vegetable","spacing":4,"daysToHarvest":100,"waterNeed":"low","sunNeed":"full","sowIndoors":-10,"transplantAfterFrost":-2,"directSow":null,"harvestWeeks":2,"companions":["carrot","lettuce","tomato","strawberry","pepper","kale","spinach","garlic","chive","beet"],"enemies":["green-beans","peas"],"notes":"Start from sets for easiest results. Long day varieties for Ohio.","seedStart":"Start from seeds 10-12 weeks before last frost (Jan 15-Feb 1) or plant onion sets as soon as soil is workable (mid-March). Use long-day varieties for Ohio.","care":"Weed carefully — shallow roots. Stop watering when tops fall over. Cure in sun for 2 weeks before storage.","lowMaintenance":true},{"id":"garlic","name":"Garlic","emoji":"🧄","type":"vegetable","spacing":6,"daysToHarvest":240,"waterNeed":"low","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":null,"harvestWeeks":2,"companions":["tomato","pepper","lettuce","strawberry","carrot","kale","spinach","onion","chive"],"enemies":["green-beans","peas"],"notes":"Plant in FALL (October). Harvest following July. Easiest crop ever.","seedStart":"Plant individual cloves in mid-October, 2\" deep, pointy end up, 6\" apart. Mulch heavily with straw. They grow roots in fall, go dormant in winter, and shoot up in spring.","care":"Almost zero effort. Remove scapes in June for bigger bulbs. Harvest when lower 1/3 of leaves are brown (July). Cure 2 weeks. ULTIMATE low-maintenance crop.","lowMaintenance":true},{"id":"corn","name":"Sweet Corn","emoji":"🌽","type":"vegetable","spacing":12,"daysToHarvest":75,"waterNeed":"high","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":2,"harvestWeeks":3,"companions":["green-beans","zucchini","cucumber","peas","sunflower","marigold"],"enemies":["tomato"],"notes":"Three Sisters crop! Plant in blocks (not rows) for pollination. Heavy feeder.","seedStart":"Direct sow 2 weeks after last frost (May 2) when soil is 60°F+. Plant 1\" deep, 12\" apart in blocks of at least 4 rows for wind pollination. Succession plant every 2 weeks through June.","care":"Heavy feeder — side-dress with compost when knee-high. Needs 1\" water/week, critical during silking. Harvest when silks are brown and kernels milky.","lowMaintenance":false},{"id":"broccoli","name":"Broccoli","emoji":"🥦","type":"vegetable","spacing":18,"daysToHarvest":70,"waterNeed":"medium","sunNeed":"full","sowIndoors":-6,"transplantAfterFrost":-2,"directSow":null,"harvestWeeks":4,"companions":["onion","garlic","beet","lettuce","spinach","dill","nasturtium","marigold","thyme","rosemary"],"enemies":["tomato","pepper","strawberry","green-beans"],"notes":"Cool-season crop. Plant spring and fall. Harvest side shoots for extended production.","seedStart":"Start indoors 6-8 weeks before last frost (Mar 1-7). Plant 1/4\" deep. Transplant 2 weeks before last frost (Apr 4). For fall crop, start indoors mid-June, transplant late July.","care":"Consistent moisture. Floating row covers prevent cabbage worms. Harvest central head when tight, then side shoots produce for weeks.","lowMaintenance":false},{"id":"cabbage","name":"Cabbage","emoji":"🥬","type":"vegetable","spacing":18,"daysToHarvest":80,"waterNeed":"medium","sunNeed":"full","sowIndoors":-6,"transplantAfterFrost":-2,"directSow":null,"harvestWeeks":3,"companions":["onion","garlic","beet","lettuce","dill","nasturtium","thyme","mint"],"enemies":["tomato","pepper","strawberry","green-beans"],"notes":"Stores very well. Great for donations. Cool-season crop.","seedStart":"Start indoors 6-8 weeks before last frost (Mar 1-7). Transplant 2 weeks before last frost (Apr 4). For fall crop, start mid-June, transplant late July.","care":"Use row covers to prevent cabbage worms. Consistent watering prevents splitting. Harvest when heads are firm. Stores 3-4 months — ideal for food bank donation.","lowMaintenance":false},{"id":"beet","name":"Beet","emoji":"🔴","type":"vegetable","spacing":4,"daysToHarvest":55,"waterNeed":"low","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":-3,"harvestWeeks":6,"companions":["onion","garlic","lettuce","kale","broccoli","cabbage","green-beans","mint"],"enemies":["swiss-chard"],"notes":"Both roots AND greens are edible. Cool-season. Succession plant.","seedStart":"Direct sow 3-4 weeks before last frost (Mar 21-28). Plant 1/2\" deep, 1\" apart, thin to 4\". Each \"seed\" is actually a cluster — thin aggressively. Succession sow every 3 weeks.","care":"Soak seeds overnight for faster germination. Thin when 2\" tall — eat the thinnings as microgreens! Both roots and greens are nutritious.","lowMaintenance":true},{"id":"swiss-chard","name":"Swiss Chard","emoji":"🌿","type":"vegetable","spacing":8,"daysToHarvest":55,"waterNeed":"medium","sunNeed":"full","sowIndoors":-3,"transplantAfterFrost":0,"directSow":-2,"harvestWeeks":16,"companions":["green-beans","peas","onion","garlic","lettuce","carrot","cabbage","kale"],"enemies":["beet","potato"],"notes":"Cut-and-come-again all season. Cold-hardy. Beautiful rainbow varieties.","seedStart":"Start indoors 3-4 weeks before last frost (Mar 28) or direct sow 2 weeks before (Apr 4). Plant 1/2\" deep. Very cold tolerant.","care":"Harvest outer leaves at 8-10\". Plant keeps producing all season. Tolerates both heat and frost. One of the most productive greens per square foot.","lowMaintenance":true},{"id":"peas","name":"Garden Peas","emoji":"🫑","type":"vegetable","spacing":3,"daysToHarvest":60,"waterNeed":"medium","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":-4,"harvestWeeks":4,"companions":["carrot","radish","green-beans","corn","cucumber","lettuce","spinach","mint"],"enemies":["onion","garlic","chive"],"notes":"Cool-season nitrogen fixer. Plant early! Needs trellis for climbing types.","seedStart":"Direct sow 4-6 weeks before last frost (Mar 7-21). Plant 1\" deep, 3\" apart. Inoculate with rhizobium for best nitrogen fixation. Do NOT start indoors.","care":"Provide trellis or netting for climbing types. Pick frequently to encourage production. Pull plants when done and plant fall crop in Aug.","lowMaintenance":true},{"id":"eggplant","name":"Eggplant","emoji":"🍆","type":"vegetable","spacing":24,"daysToHarvest":80,"waterNeed":"medium","sunNeed":"full","sowIndoors":-8,"transplantAfterFrost":3,"directSow":null,"harvestWeeks":10,"companions":["green-beans","pepper","marigold","nasturtium","thyme","oregano"],"enemies":["fennel"],"notes":"Needs warm soil and long season. Very productive once established.","seedStart":"Start indoors 8-10 weeks before last frost (Feb 15-Mar 1). Needs warmth (75-85°F) for germination. Transplant 3 weeks after last frost (May 9) when nights stay above 60°F.","care":"Mulch heavily. Stake or cage for support when heavy with fruit. Harvest when skin is glossy and firm.","lowMaintenance":false},{"id":"potato","name":"Potato","emoji":"🥔","type":"vegetable","spacing":12,"daysToHarvest":90,"waterNeed":"medium","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":-2,"harvestWeeks":3,"companions":["green-beans","corn","cabbage","broccoli","marigold","nasturtium","thyme"],"enemies":["tomato","pepper","eggplant","cucumber","zucchini","sunflower","cantaloupe"],"notes":"Plant seed potatoes, not grocery store potatoes. Hill soil as they grow. Massive yield.","seedStart":"Plant seed potato pieces 2-3 weeks before last frost (Apr 1-4). Cut into pieces with 2-3 eyes each, cure cut sides 2 days. Plant 4\" deep, 12\" apart.","care":"Hill soil 6\" around stems twice during growing. Stop watering when foliage yellows. Harvest when tops die back. Cure in cool dark place for storage.","lowMaintenance":true},{"id":"strawberry","name":"Strawberry","emoji":"🍓","type":"fruit","spacing":12,"daysToHarvest":90,"waterNeed":"medium","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":0,"directSow":null,"harvestWeeks":4,"companions":["lettuce","spinach","green-beans","thyme","onion","garlic","chive","marigold","nasturtium","borage"],"enemies":["cabbage","broccoli"],"notes":"Perennial! Plant once, harvest for years. Use bare root transplants.","seedStart":"Purchase bare root crowns. Plant as soon as soil is workable (mid-April). Set crown at soil level. Pinch first-year flowers on June-bearers for bigger second-year crop.","care":"Mulch with straw to keep fruit clean. Remove runners unless you want spreading. Very low maintenance once established.","lowMaintenance":true},{"id":"cantaloupe","name":"Cantaloupe","emoji":"🍈","type":"fruit","spacing":36,"daysToHarvest":85,"waterNeed":"medium","sunNeed":"full","sowIndoors":-3,"transplantAfterFrost":2,"directSow":2,"harvestWeeks":4,"companions":["corn","sunflower","marigold","nasturtium","radish","lettuce"],"enemies":["potato","cucumber"],"notes":"Space hog — needs room to sprawl. Warm soil essential.","seedStart":"Start indoors 3-4 weeks before last frost (Mar 28). Use peat pots to avoid root disturbance. Transplant after May 1 when soil is 65°F+.","care":"Black plastic mulch warms soil. Reduce water as fruit ripens. Slip test: ripe when stem separates easily.","lowMaintenance":false},{"id":"blueberry","name":"Blueberry","emoji":"🫐","type":"fruit","spacing":48,"daysToHarvest":365,"waterNeed":"medium","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":0,"directSow":null,"harvestWeeks":6,"companions":["strawberry","thyme","basil","borage","chive"],"enemies":["tomato","pepper","eggplant"],"notes":"Perennial shrub. Needs acidic soil (pH 4.5-5.5). Use sulfur or peat to lower pH. Produces fruit in year 2-3. Grows 4-6 ft tall (highbush).","seedStart":"Plant bare root or potted nursery stock in early spring (April). Dig hole twice root ball width. Amend soil with peat moss & sulfur for acidity. Space 4 ft apart.","care":"Mulch heavily with pine needles or wood chips (acidifying). Water consistently — 1-2 inches/week. Prune oldest canes in late winter. Net fruit to protect from birds. Needs 2+ varieties for cross-pollination.","lowMaintenance":true},{"id":"basil","name":"Basil","emoji":"🌿","type":"herb","spacing":10,"daysToHarvest":60,"waterNeed":"medium","sunNeed":"full","sowIndoors":-6,"transplantAfterFrost":2,"directSow":2,"harvestWeeks":14,"companions":["tomato","pepper","marigold","lettuce","oregano","parsley"],"enemies":["sage","rue"],"notes":"Classic tomato companion. Pinch flowers for bushy growth.","seedStart":"Start indoors 6-8 weeks before last frost (Mar 1-7). Surface sow, press into soil. Needs light & warmth (70°F+). Transplant after all frost danger.","care":"Pinch growing tips regularly for bushy plants. Harvest before flowering. Very frost-sensitive — cover or harvest at season end.","lowMaintenance":true},{"id":"chive","name":"Chives","emoji":"🌾","type":"herb","spacing":8,"daysToHarvest":60,"waterNeed":"low","sunNeed":"full","sowIndoors":-8,"transplantAfterFrost":0,"directSow":0,"harvestWeeks":20,"companions":["carrot","tomato","strawberry","lettuce","onion","garlic"],"enemies":["green-beans","peas"],"notes":"Perennial! Returns every year. Pest deterrent. Edible flowers.","seedStart":"Start indoors 8-10 weeks before last frost (Feb 15) or buy transplants. Very slow from seed. Easier to divide existing clumps.","care":"Perennial — plant once, harvest for years. Cut back to 2\" periodically for fresh growth. Divide clumps every 3 years.","lowMaintenance":true},{"id":"parsley","name":"Parsley","emoji":"☘","type":"herb","spacing":8,"daysToHarvest":75,"waterNeed":"medium","sunNeed":"partial","sowIndoors":-8,"transplantAfterFrost":-2,"directSow":-2,"harvestWeeks":20,"companions":["tomato","pepper","carrot","chive","green-beans","lettuce"],"enemies":["mint"],"notes":"Biennial. Attracts swallowtail butterflies. Extremely versatile culinary herb.","seedStart":"Start indoors 8-10 weeks before last frost (Feb 15). SLOW germinator — soak seeds 24hrs first, takes 3-4 weeks to sprout. Or direct sow 2 weeks before last frost (Apr 4).","care":"Slow to start but very productive. Cut outer stems to harvest. Biennial — let a few plants flower in year 2 for swallowtail butterfly host. Cold hardy into November.","lowMaintenance":true},{"id":"cilantro","name":"Cilantro","emoji":"🌿","type":"herb","spacing":4,"daysToHarvest":45,"waterNeed":"medium","sunNeed":"partial","sowIndoors":null,"transplantAfterFrost":null,"directSow":-2,"harvestWeeks":3,"companions":["tomato","pepper","green-beans","peas","lettuce","spinach"],"enemies":["fennel","dill"],"notes":"Bolts fast in heat. Succession sow! Seeds = coriander. Culturally essential.","seedStart":"Direct sow 2 weeks before last frost (Apr 4). Plant 1/4\" deep, scatter thickly. Succession sow every 2-3 weeks through May, resume in Sept.","care":"Bolts to seed rapidly in warm weather. Plant in partial shade in summer. Let some bolt — coriander seeds are a valuable spice. Self-seeds readily.","lowMaintenance":true},{"id":"oregano","name":"Oregano","emoji":"🌿","type":"herb","spacing":12,"daysToHarvest":60,"waterNeed":"low","sunNeed":"full","sowIndoors":-6,"transplantAfterFrost":0,"directSow":0,"harvestWeeks":20,"companions":["tomato","pepper","green-beans","broccoli","cabbage","kale","basil","thyme"],"enemies":[],"notes":"Perennial! Returns every year in Zone 6a. Good all-around companion plant.","seedStart":"Start indoors 6-8 weeks before last frost (Mar 1-7) or buy transplants (easier). Tiny seeds — surface sow, press gently. Perennial in Zone 6a.","care":"Extremely low maintenance. Cut back by 1/3 before flowering for best flavor. Drought tolerant. Mulch in fall for winter protection.","lowMaintenance":true},{"id":"dill","name":"Dill","emoji":"🌿","type":"herb","spacing":8,"daysToHarvest":55,"waterNeed":"low","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":0,"harvestWeeks":8,"companions":["cucumber","lettuce","onion","zucchini","kale","green-beans","broccoli","cabbage"],"enemies":["carrot","tomato"],"notes":"Self-seeds aggressively. Attracts beneficial insects. Easy pickles!","seedStart":"Direct sow after last frost (Apr 18). Scatter seeds, press into soil. Barely cover. Self-seeds like crazy — you'll have it forever after one planting.","care":"Let some plants go to seed for next year's crop. Attracts swallowtail butterflies. Harvest leaves anytime, seeds when brown.","lowMaintenance":true},{"id":"mint","name":"Mint","emoji":"🌿","type":"herb","spacing":12,"daysToHarvest":60,"waterNeed":"medium","sunNeed":"partial","sowIndoors":null,"transplantAfterFrost":0,"directSow":null,"harvestWeeks":20,"companions":["tomato","cabbage","peas","kale","lettuce"],"enemies":["parsley"],"notes":"WARNING: Invasive spreader! ALWAYS plant in containers, never directly in beds.","seedStart":"Buy transplants — do NOT direct sow in beds. MUST be contained in a pot sunk into the bed or it will take over everything. Plant after last frost.","care":"Will aggressively spread if not contained. Grow in sunken pots within beds. Cut back hard periodically. Perennial and virtually unkillable.","lowMaintenance":true},{"id":"thyme","name":"Thyme","emoji":"🌿","type":"herb","spacing":8,"daysToHarvest":70,"waterNeed":"low","sunNeed":"full","sowIndoors":-8,"transplantAfterFrost":0,"directSow":null,"harvestWeeks":20,"companions":["strawberry","tomato","cabbage","oregano","marigold","eggplant","potato","broccoli"],"enemies":[],"notes":"Perennial ground cover. Drought champion. Practically unkillable.","seedStart":"Start indoors 8-10 weeks before last frost (Feb 15) or buy transplants (much easier). Slow from seed. Perennial in Zone 6a.","care":"Nearly indestructible. Drought tolerant. Cut back by 1/3 in spring. Never overwater. Spreading varieties make great ground cover between beds.","lowMaintenance":true},{"id":"rosemary","name":"Rosemary","emoji":"🌿","type":"herb","spacing":18,"daysToHarvest":80,"waterNeed":"low","sunNeed":"full","sowIndoors":-10,"transplantAfterFrost":2,"directSow":null,"harvestWeeks":20,"companions":["carrot","green-beans","broccoli","cabbage","kale","pepper"],"enemies":["cucumber","zucchini"],"notes":"Treat as annual in Zone 6a (may overwinter with heavy protection). Repels many pests.","seedStart":"Buy transplants — very slow and unreliable from seed. Plant after last frost (Apr 18). In Zone 6a, treat as annual or bring pots indoors for winter.","care":"Excellent drought tolerance. Do not overwater. Repels cabbage moths, carrot rust flies, and bean beetles. Bring potted plants indoors before first frost.","lowMaintenance":true},{"id":"borage","name":"Borage","emoji":"🌺","type":"herb","spacing":18,"daysToHarvest":55,"waterNeed":"low","sunNeed":"full","sowIndoors":-4,"transplantAfterFrost":0,"directSow":0,"harvestWeeks":12,"companions":["tomato","strawberry","zucchini","cucumber","green-beans"],"enemies":[],"notes":"Top-tier companion plant. Massive pollinator attractor. Edible flowers.","seedStart":"Start indoors 4-6 weeks before last frost (Mar 14-28) or direct sow after last frost (Apr 18). Plant 1/4-1/2\" deep. Self-seeds vigorously.","care":"Grows large (2-3 feet). Stake to prevent flopping. Attracts bees and parasitic wasps that control hornworms. Edible star-shaped blue flowers.","lowMaintenance":true},{"id":"sweet-peas","name":"Sweet Peas","emoji":"🌼","type":"flower","spacing":6,"daysToHarvest":65,"waterNeed":"medium","sunNeed":"full","sowIndoors":-6,"transplantAfterFrost":-2,"directSow":-4,"harvestWeeks":8,"companions":["green-beans","carrot","radish"],"enemies":["onion","garlic"],"notes":"Beautiful cut flowers. Cool season — plant early. Needs trellis. NOT edible (ornamental only).","seedStart":"Soak seeds 24hrs. Start indoors 6 weeks before last frost (Mar 7) or direct sow 4 weeks before (Mar 21). Nick seed coat with file before soaking.","care":"Provide trellis or netting. Keep soil cool with mulch. Deadhead regularly for continuous bloom.","lowMaintenance":true},{"id":"marigold","name":"Marigold","emoji":"🌻","type":"flower","spacing":8,"daysToHarvest":50,"waterNeed":"low","sunNeed":"full","sowIndoors":-6,"transplantAfterFrost":0,"directSow":0,"harvestWeeks":16,"companions":["tomato","pepper","green-beans","zucchini","cucumber","strawberry","nasturtium","eggplant","potato","broccoli"],"enemies":[],"notes":"Pest deterrent powerhouse. Plant everywhere as companion. Deer resistant.","seedStart":"Start indoors 6-8 weeks before last frost (Mar 1) or direct sow after last frost (Apr 18). Easy germinators. Cover lightly with soil.","care":"Nearly indestructible. Deadhead for continuous bloom. Drought tolerant once established. French marigolds best for pest control.","lowMaintenance":true},{"id":"nasturtium","name":"Nasturtium","emoji":"🌺","type":"flower","spacing":10,"daysToHarvest":55,"waterNeed":"low","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":0,"harvestWeeks":14,"companions":["tomato","cucumber","zucchini","green-beans","radish","kale","strawberry","marigold","broccoli","cabbage","potato"],"enemies":[],"notes":"Edible! Trap crop for aphids. Thrives in poor soil. Zero maintenance.","seedStart":"Direct sow after last frost (Apr 18). Plant 1/2\" deep. Large seeds, easy to handle. Nick seed coat for faster germination.","care":"Thrives on neglect. Poor soil = more flowers. Do NOT fertilize. Edible flowers and leaves (peppery). Trap crop attracts aphids away from veggies.","lowMaintenance":true},{"id":"sunflower","name":"Sunflower","emoji":"🌻","type":"flower","spacing":18,"daysToHarvest":80,"waterNeed":"low","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":1,"harvestWeeks":4,"companions":["cucumber","corn","zucchini","lettuce","green-beans"],"enemies":["potato"],"notes":"Pollinators love them. Community engagement magnet. Seeds for birds.","seedStart":"Direct sow 1 week after last frost (Apr 25). Plant 1\" deep. Fast growers. Succession plant every 2 weeks for continuous bloom.","care":"Water regularly until established, then drought tolerant. Stake tall varieties. Leave seed heads for birds in fall — great community engagement.","lowMaintenance":true},{"id":"tomato-cherokee-purple","name":"Tomato - Cherokee Purple","emoji":"🍅","type":"vegetable","spacing":30,"daysToHarvest":82,"waterNeed":"medium","sunNeed":"full","sowIndoors":-6,"transplantAfterFrost":2,"directSow":null,"harvestWeeks":10,"companions":["basil","marigold","carrot","parsley","onion","garlic","chive","nasturtium"],"enemies":["cabbage","fennel","dill","potato","broccoli","kale"],"notes":"Heirloom indeterminate. 10-12 oz pink-purple fruit with smoky, sweet flavor. Disease tolerant. Certified organic (Ferry-Morse).","seedStart":"Start indoors 6 weeks before last frost in sunny location. Plant 1/4\" deep. Germination 7-10 days. Transplant outdoors when seedlings have 4-6 leaves and weather is warm.","care":"Indeterminate vines — stake or cage. Cannot tolerate frost. Can also direct sow when soil is warm. Space 2.5 ft apart, 2 ft rows.","lowMaintenance":false},{"id":"tomato-red-brandywine","name":"Tomato - Red Brandywine","emoji":"🍅","type":"vegetable","spacing":24,"daysToHarvest":90,"waterNeed":"medium","sunNeed":"full","sowIndoors":-7,"transplantAfterFrost":2,"directSow":null,"harvestWeeks":10,"companions":["basil","marigold","carrot","parsley","onion","garlic","chive","nasturtium"],"enemies":["cabbage","fennel","dill","potato","broccoli","kale"],"notes":"Heirloom indeterminate. Deep red, avg 8 oz fruits with well-balanced flavor. Disease tolerant. Needs staking — few but large fruit. (Livingston)","seedStart":"Start indoors 6-8 weeks before last frost. Plant 1/4\" deep. Transplant to 2 ft spacing after danger of frost when soil warms.","care":"Indeterminate — stake heavily. Produces fewer but larger fruit than most varieties. Direct sow also possible after frost.","lowMaintenance":false},{"id":"tomato-roma","name":"Tomato - Roma","emoji":"🍅","type":"vegetable","spacing":36,"daysToHarvest":80,"waterNeed":"medium","sunNeed":"full","sowIndoors":-6,"transplantAfterFrost":2,"directSow":null,"harvestWeeks":8,"companions":["basil","marigold","carrot","parsley","onion","garlic","chive","nasturtium"],"enemies":["cabbage","fennel","dill","potato","broccoli","kale"],"notes":"Determinate paste tomato. Heavy yields, little juice, mild flavor. Good leaf cover. Disease tolerant. Ideal for preserves, canning, and puree. (Ferry-Morse)","seedStart":"Start indoors 6 weeks before warm weather. Plant 1/4\" deep. Germination 7-10 days. Transplant at 4-6 leaves when weather is warm. Space 3 ft apart, 2 ft rows.","care":"Determinate — more compact than indeterminate. Cannot tolerate frost. Harvest when firm and deep red.","lowMaintenance":true},{"id":"tomato-better-boy","name":"Tomato - Better Boy Hybrid","emoji":"🍅","type":"vegetable","spacing":24,"daysToHarvest":80,"waterNeed":"medium","sunNeed":"full","sowIndoors":-6,"transplantAfterFrost":2,"directSow":null,"harvestWeeks":10,"companions":["basil","marigold","carrot","parsley","onion","garlic","chive","nasturtium"],"enemies":["cabbage","fennel","dill","potato","broccoli","kale"],"notes":"Hybrid indeterminate. Extra-large fruits up to 1.5 lbs. Deep red, smooth, firm, meaty. Tolerant of CFN, ASC, and ST diseases. (Ferry-Morse)","seedStart":"Start indoors 6 weeks before warm weather. Plant 1/4\" deep. Germination 8-10 days. Transplant at 4-6 leaves. Space 2 ft apart, 2 ft rows.","care":"Vigorous indeterminate — stake or cage. Cannot tolerate frost. Seeds can be sown directly when soil is warm.","lowMaintenance":false},{"id":"tomato-mortgage-lifter","name":"Tomato - Mortgage Lifter","emoji":"🍅","type":"vegetable","spacing":30,"daysToHarvest":82,"waterNeed":"medium","sunNeed":"full","sowIndoors":-5,"transplantAfterFrost":2,"directSow":null,"harvestWeeks":10,"companions":["basil","marigold","carrot","parsley","onion","garlic","chive","nasturtium"],"enemies":["cabbage","fennel","dill","potato","broccoli","kale"],"notes":"Heirloom indeterminate. Avg 2.5 lbs each, deep pink, sweet, large and meaty with few seeds. Developed 1930s in Logan, WV. (Livingston)","seedStart":"Start indoors 4-6 weeks before last frost. Plant 1/4\" in flats or pots. Transplant seedlings 18-36\" apart.","care":"Indeterminate — staking required due to large fruit size. Produces fewer but massive fruit.","lowMaintenance":false},{"id":"onion-evergreen-bunching","name":"Onion - Evergreen Bunching","emoji":"🧅","type":"vegetable","spacing":3,"daysToHarvest":60,"waterNeed":"low","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":-4,"harvestWeeks":8,"companions":["carrot","lettuce","tomato","strawberry","pepper","kale","spinach"],"enemies":["green-beans","peas"],"notes":"Green bunching onion. Crisp and mild, great in salads and as appetizer. Certified organic (Ferry-Morse).","seedStart":"Sow directly in full sun and well-drained soil. Plant 2-3 seeds per inch, 1/4-1/2\" deep. Thin to 3\" apart when 3\" tall. Germination 10-12 days.","care":"Begin pulling when pencil-thick. 12\" between rows. Can be harvested at any size.","lowMaintenance":true},{"id":"carrot-chantenay","name":"Carrot - Chantenay","emoji":"🥕","type":"vegetable","spacing":3,"daysToHarvest":70,"waterNeed":"medium","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":-2,"harvestWeeks":4,"companions":["tomato","lettuce","onion","radish","peas","chive","rosemary"],"enemies":["dill","parsley"],"notes":"Heirloom from the mid-1800s. Tender, crisp 5-7\" conical roots with strong tops. Good for storage, canning, and freezing. (Livingston)","seedStart":"Direct sow 2 weeks before last frost. Plant 1/2-3/4\" deep. Thin to 2-4\" apart.","care":"Keep soil consistently moist for germination. Shape and color may vary with soil type and temperature. Lower temps may give yellower roots.","lowMaintenance":true},{"id":"beet-bulls-blood","name":"Beet - Bull's Blood","emoji":"🔴","type":"vegetable","spacing":4,"daysToHarvest":46,"waterNeed":"medium","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":1,"harvestWeeks":3,"companions":["onion","garlic","lettuce","spinach","kale","cabbage","broccoli"],"enemies":["green-beans"],"notes":"Deep red ornamental leaves — great in salad mixes. Tasty roots too. Harvest roots at 2-3\". Adds color to flower gardens. Height 1-2 ft. (Livingston)","seedStart":"Direct sow when soil warms after last frost. Plant 1/2\" deep.","care":"Dual purpose — harvest both sweet leaves and roots. Thin progressively.","lowMaintenance":true},{"id":"beet-early-wonder","name":"Beet - Tall Top Early Wonder","emoji":"🔴","type":"vegetable","spacing":4,"daysToHarvest":60,"waterNeed":"medium","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":-4,"harvestWeeks":3,"companions":["onion","garlic","lettuce","spinach","kale","cabbage","broccoli"],"enemies":["green-beans"],"notes":"All-purpose table beet. Flattened globe roots with purplish-red flesh. High in vitamins A, B2, B6, C. Certified organic (Ferry-Morse).","seedStart":"Sow as early as ground can be worked. Plant 1\" deep, press down firmly. Rows 18\" apart, thin to 4\". Germination 8-10 days.","care":"When tops are 6\", pull plants until 4\" apart. Harvest when roots are 3\" diameter.","lowMaintenance":true},{"id":"pumpkin-big-max","name":"Pumpkin - Big Max","emoji":"🎃","type":"vegetable","spacing":96,"daysToHarvest":120,"waterNeed":"medium","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":2,"harvestWeeks":2,"companions":["corn","green-beans","marigold","nasturtium","radish"],"enemies":["potato"],"notes":"Giant pumpkin — up to 6 ft diameter and 100+ lbs! Round to flattened-round, pinkish-orange. Excellent for prize pumpkins. Certified organic (Ferry-Morse).","seedStart":"Sow 3 seeds per hill (9-12\" tall, 1 ft across) after frost danger. Full sun. Plant 1-1.5\" deep. Germination 7-10 days.","care":"Thin to 2 per hill at 1\" tall, then strongest at 3\". Heavy organic mulch. Space hills 8 ft apart.","lowMaintenance":false},{"id":"watermelon-crimson-sweet","name":"Watermelon - Crimson Sweet","emoji":"🍉","type":"vegetable","spacing":60,"daysToHarvest":80,"waterNeed":"high","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":2,"harvestWeeks":3,"companions":["corn","marigold","nasturtium","radish","sunflower"],"enemies":["potato"],"notes":"Sweet, deep red flesh with dark green striped rind. Round melons up to 25 lbs. High in vitamins A, B, C. Certified organic (Ferry-Morse).","seedStart":"Sow 4-5 seeds per hill (12\" tall, 2 ft across) in full sun after frost. Plant 1/2\" deep. Germination 6-8 days. Thin to 3 per hill at 6\".","care":"Do not disturb roots. 5 ft between plants, 6 ft between rows. Water consistently.","lowMaintenance":false},{"id":"watermelon-petite-yellow","name":"Watermelon - Petite Yellow","emoji":"🍉","type":"vegetable","spacing":72,"daysToHarvest":72,"waterNeed":"high","sunNeed":"full","sowIndoors":-4,"transplantAfterFrost":2,"directSow":2,"harvestWeeks":3,"companions":["corn","marigold","nasturtium","radish","sunflower"],"enemies":["potato"],"notes":"Compact variety with bright yellow flesh, 6-10 lbs. Sweet and aromatic. Space-saving. Not frost hardy. (Livingston)","seedStart":"Start indoors 4 weeks before last frost, or direct sow after danger of frost and soil warms. Plant 1/2\" deep. Thin to 6-8 ft apart.","care":"Water regularly but do not overwater. More compact than other watermelons.","lowMaintenance":false},{"id":"watermelon-dixie-queen","name":"Watermelon - Dixie Queen","emoji":"🍉","type":"vegetable","spacing":72,"daysToHarvest":85,"waterNeed":"high","sunNeed":"full","sowIndoors":-4,"transplantAfterFrost":2,"directSow":2,"harvestWeeks":3,"companions":["corn","marigold","nasturtium","radish","sunflower"],"enemies":["potato"],"notes":"Heirloom. Earlier-to-harvest, 40-50 lbs with dark green and ivory stripes. Crisp red flesh, exceptionally sweet. (Livingston)","seedStart":"Start indoors 4 weeks before last frost, or direct sow after frost/soil warms. Plant 1/2\" deep. Thin to 6-8 ft apart.","care":"Harvest when bottom turns yellow and stem curlicue dries.","lowMaintenance":false},{"id":"cantaloupe-hearts-of-gold","name":"Cantaloupe - Hearts of Gold","emoji":"🍈","type":"vegetable","spacing":36,"daysToHarvest":90,"waterNeed":"medium","sunNeed":"full","sowIndoors":-4,"transplantAfterFrost":2,"directSow":1,"harvestWeeks":3,"companions":["corn","sunflower","marigold","nasturtium","radish","lettuce"],"enemies":["potato","cucumber"],"notes":"Heirloom developed 1895. Most popular Midwest variety in 1930s. Almost round, ~3 lb melons with sweet, deep orange flesh. (Livingston)","seedStart":"Start indoors 4 weeks before last frost. Plant 1/4\" deep. Thin to 36\" apart. Direct sow after danger of frost.","care":"Needs warm soil and full sun. Harvest when stem slips easily from fruit.","lowMaintenance":false},{"id":"cantaloupe-delicious-51","name":"Cantaloupe - Delicious 51","emoji":"🍈","type":"vegetable","spacing":36,"daysToHarvest":80,"waterNeed":"medium","sunNeed":"full","sowIndoors":-4,"transplantAfterFrost":2,"directSow":1,"harvestWeeks":3,"companions":["corn","sunflower","marigold","nasturtium","radish","lettuce"],"enemies":["potato","cucumber"],"notes":"Salmon-orange flesh, very sweet and aromatic. 5-6\" oval, 3-4 lbs. Lightly netted rind. (Livingston)","seedStart":"Start indoors 3-4 weeks before last frost, or direct sow after frost. Plant 1/2\" deep. Space 3 ft apart in raised rows or hills.","care":"Sunny, warm location with well-drained soil. Harvest when stem slips easily.","lowMaintenance":false},{"id":"squash-cocozelle","name":"Squash - Cocozelle","emoji":"🥜","type":"vegetable","spacing":21,"daysToHarvest":50,"waterNeed":"medium","sunNeed":"full","sowIndoors":-3,"transplantAfterFrost":1,"directSow":1,"harvestWeeks":8,"companions":["corn","green-beans","radish","marigold","nasturtium","borage"],"enemies":["potato"],"notes":"Italian zucchini with bush habit. Dark green with lighter stripes. Firm, greenish-white flesh. Good in containers and small gardens. Good for freezing/canning. (Livingston)","seedStart":"Start indoors 14-21 days before last frost, or direct sow after frost. Plant 1/2-3/4\" deep. Thin to 18-24\" apart.","care":"Best harvested at 12\" or shorter. Pick often for prolonged harvest.","lowMaintenance":true},{"id":"cucumber-national-pickling","name":"Cucumber - National Pickling","emoji":"🥒","type":"vegetable","spacing":48,"daysToHarvest":55,"waterNeed":"high","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":2,"harvestWeeks":6,"companions":["green-beans","peas","lettuce","sunflower","radish","dill","marigold","nasturtium","corn"],"enemies":["potato","sage","rosemary"],"notes":"Very high-yielding vines. Crispy, tender-skinned blocky fruit. Top-notch for pickling when harvested young. Certified organic (Ferry-Morse).","seedStart":"Sow a few seeds per hill (12\" tall, 2 ft across) in full sun with well-drained soil. Plant 1/2\" deep. Germination 8-10 days. Thin to 3 per hill at 2\".","care":"Trellis for smaller gardens. Succession plant every 3 weeks for all-season cucumbers. Keep fruits picked. 4 ft / 6 ft spacing.","lowMaintenance":false},{"id":"cowpeas-california-blackeye","name":"Cowpeas - California Blackeye","emoji":"🫘","type":"vegetable","spacing":3,"daysToHarvest":80,"waterNeed":"medium","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":2,"harvestWeeks":4,"companions":["corn","cucumber","radish"],"enemies":["onion","garlic","fennel"],"notes":"Bushy plants produce 7\" pods with greenish-white peas marked with a black eye. Most popular southern pea. Tender and delicious. Certified organic (Ferry-Morse).","seedStart":"Sow directly in full sun after soil warms. Plant 2 seeds every 3\", 1\" deep. Germination 7-10 days. Thin to 1 per 3\" when they have 4 leaves.","care":"Keep soil moist. Space rows 3 ft apart. Heat-loving crop.","lowMaintenance":true},{"id":"lettuce-lolla-rossa","name":"Lettuce - Lolla Rossa","emoji":"🥬","type":"vegetable","spacing":10,"daysToHarvest":50,"waterNeed":"medium","sunNeed":"full","sowIndoors":-5,"transplantAfterFrost":0,"directSow":1,"harvestWeeks":6,"companions":["carrot","radish","strawberry","chive","onion","garlic","green-beans","peas"],"enemies":[],"notes":"Beautiful magenta, frilly leaves with light green base. Mild and tasty. Excellent cut-and-come-again. Decorative in containers. (Livingston)","seedStart":"Start indoors 4-6 weeks before last frost, or direct sow after frost. Plant 1/4\" deep. Thin to 8-12\". Height 6-12\".","care":"Pick outer leaves as they grow, or harvest whole. Crisper in cooler temps.","lowMaintenance":true},{"id":"pea-early-frosty","name":"Pea - Early Frosty","emoji":"🫑","type":"vegetable","spacing":3,"daysToHarvest":62,"waterNeed":"medium","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":-6,"harvestWeeks":3,"companions":["carrot","radish","cucumber","corn","lettuce","spinach"],"enemies":["onion","garlic","chive"],"notes":"Vigorous, heavy producer of 4\" double pods with 7-8 sweet peas. Easy to pick, wilt resistant. Good for short seasons and cold springs. (Livingston)","seedStart":"Direct sow as soon as soil can be worked. Plant 1/2-3/4\" deep, 1-3\" apart. Height 28-30\".","care":"Train on stakes or trellis. Succession plant every 2 weeks through midspring, resume in late summer for fall crop.","lowMaintenance":true},{"id":"pea-lincoln","name":"Pea - Lincoln","emoji":"🫑","type":"vegetable","spacing":8,"daysToHarvest":62,"waterNeed":"medium","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":-6,"harvestWeeks":3,"companions":["carrot","radish","cucumber","corn","lettuce","spinach"],"enemies":["onion","garlic","chive"],"notes":"High yields of sweet, tender peas. 4-5\" pods with 6-9 peas. Heat and wilt tolerant. Great fresh, canned, or frozen. Ideal for fall crop. (Livingston)","seedStart":"Direct sow as soon as soil can be worked. Plant 3/4-1\" deep. Thin to 8\". Height 24-30\".","care":"Sow in double rows with trellis between for easy harvest. Succession plant every 2 weeks.","lowMaintenance":true},{"id":"arugula-roquette","name":"Arugula - Roquette","emoji":"🥬","type":"vegetable","spacing":9,"daysToHarvest":40,"waterNeed":"medium","sunNeed":"partial","sowIndoors":null,"transplantAfterFrost":null,"directSow":-4,"harvestWeeks":4,"companions":["lettuce","spinach","carrot","onion","chive"],"enemies":[],"notes":"Mustard family. Long, smooth leaves with pungent taste. Best as greens and in salads when young. Certified organic (Ferry-Morse).","seedStart":"Sow as soon as ground can be worked. Plant 1 seed every 3\", 1/4\" deep. Thin when established. Germination 8-10 days.","care":"Pick outer leaves for regular use. Rows 14\" apart, plants 9\" apart.","lowMaintenance":true},{"id":"spinach-america","name":"Spinach - America","emoji":"🍃","type":"vegetable","spacing":8,"daysToHarvest":50,"waterNeed":"medium","sunNeed":"partial","sowIndoors":null,"transplantAfterFrost":null,"directSow":-4,"harvestWeeks":4,"companions":["strawberry","peas","green-beans","lettuce","radish","kale"],"enemies":["potato"],"notes":"Heirloom savoy-leafed (curly) variety, ~12\" wide. Outstanding flavor. Drought and heat tolerant compact variety. Spring and fall sowing. (Livingston)","seedStart":"Direct sow when soil is 50-70°F — spring and fall. Plant 1/2-1\" deep. Thin to 6-10\". Height ~8\".","care":"Harvest dark leaves before bolting. Grow in cold frames for winter salads. Can freeze for later.","lowMaintenance":true},{"id":"dill-mammoth","name":"Dill - Mammoth","emoji":"🌿","type":"herb","spacing":9,"daysToHarvest":67,"waterNeed":"low","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":1,"harvestWeeks":4,"companions":["lettuce","cucumber","onion","cabbage","corn"],"enemies":["carrot","tomato"],"notes":"Annual herb. Highly aromatic. Use for dill pickles, salads, soups, meat, fish. Certified organic (Ferry-Morse).","seedStart":"Sow directly in well-drained soil in sunny location. Plant 1/4\" deep. Germination 7-14 days. Thin to 9\" apart when 2\" tall.","care":"Harvest when lower part of seed cluster is ripe. Let some go to seed for self-sowing.","lowMaintenance":true},{"id":"basil-sweet","name":"Basil - Sweet","emoji":"🌿","type":"herb","spacing":10,"daysToHarvest":85,"waterNeed":"medium","sunNeed":"full","sowIndoors":-6,"transplantAfterFrost":1,"directSow":1,"harvestWeeks":12,"companions":["tomato","pepper","oregano","marigold"],"enemies":["sage"],"notes":"Annual herb. Spicy flavor, pleasing aroma. Excellent tomato companion. Certified organic (Ferry-Morse).","seedStart":"Start indoors 6 weeks before transplanting near sunny window, or direct sow after frost in full sun. Plant 1/4\" deep. Germination 5-10 days.","care":"Rows 2 ft apart, thin to 10\". Pinch flower buds for longer leaf harvest.","lowMaintenance":true},{"id":"parsley-flat-italian","name":"Parsley - Flat Italian","emoji":"☘","type":"herb","spacing":10,"daysToHarvest":75,"waterNeed":"medium","sunNeed":"partial","sowIndoors":-6,"transplantAfterFrost":null,"directSow":-4,"harvestWeeks":16,"companions":["tomato","corn","asparagus"],"enemies":["lettuce","mint"],"notes":"Biennial herb. Very nice flavor for fresh use and drying. Dark green flat leaves. Easy to grow. Certified organic (Ferry-Morse).","seedStart":"Soak seeds overnight in warm water. Start indoors 6 weeks before planting, or sow in rich, moist soil as early as ground can be worked. Plant 1/4\" deep. Germination 21-28 days.","care":"Thin to 10\" apart when 2\" tall. Cut only 2-3 stems at a time. Sun or partial shade.","lowMaintenance":true},{"id":"catnip","name":"Catnip","emoji":"🌿","type":"herb","spacing":20,"daysToHarvest":72,"waterNeed":"low","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":1,"harvestWeeks":8,"companions":["squash","pumpkin","cucumber"],"enemies":[],"notes":"Perennial herb (mint family). Lemony-mint flavor for cooking and tea. Attracts cats and bees. Certified organic (Ferry-Morse).","seedStart":"Sow directly in full sun, ordinary well-drained soil. Plant 1/4\" deep. Germination 8-12 days. Thin to 20\" when 2\" tall.","care":"Pinch back shoot tops for bushy plants when buds appear. Pick leaves as needed.","lowMaintenance":true},{"id":"california-poppy-mission-bells","name":"California Poppy - Mission Bells","emoji":"🌺","type":"flower","spacing":6,"daysToHarvest":80,"waterNeed":"low","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":-4,"harvestWeeks":10,"companions":["marigold","zinnia","nasturtium"],"enemies":[],"notes":"Free-flowering bell-shaped blooms in shimmering jewel tones. Drought tolerant and sturdy. Perfect for rock gardens and containers. Reseeds in mild climates. (Ferry-Morse)","seedStart":"In early spring, sow in open ground well exposed. Cover with 1/4\" soil. In mild climates, plant fall or winter. Germination 10-12 days. Thin when 2\" high.","care":"Does not transplant easily. Height 12\". Days to bloom: 70-90.","lowMaintenance":true},{"id":"marigold-crackerjack","name":"Marigold - Crackerjack Mixed","emoji":"🌻","type":"flower","spacing":12,"daysToHarvest":52,"waterNeed":"low","sunNeed":"full","sowIndoors":-7,"transplantAfterFrost":1,"directSow":1,"harvestWeeks":14,"companions":["tomato","pepper","cucumber","eggplant","green-beans","potato"],"enemies":[],"notes":"Half-hardy annual. Huge flowers in orange, gold, yellow, primrose. Blooms midsummer to first frost. Height 2-3 ft. (Ferry-Morse)","seedStart":"After frost, sow in open ground 1/4\" deep. For earlier bloom, start indoors 6-8 weeks before last frost. Germination 5-8 days. Thin/transplant when 2\" high. Harden off.","care":"Deadhead for continuous bloom. Great pest deterrent in vegetable gardens. Days to bloom: 45-60.","lowMaintenance":true},{"id":"marigold-french-dwarf","name":"Marigold - French Double Dwarf","emoji":"🌻","type":"flower","spacing":8,"daysToHarvest":52,"waterNeed":"low","sunNeed":"full","sowIndoors":-7,"transplantAfterFrost":1,"directSow":1,"harvestWeeks":16,"companions":["tomato","pepper","cucumber","eggplant","green-beans","potato"],"enemies":[],"notes":"Half-hardy annual. Compact plants, showy double flowers in Gold, Orange, Harmony — All-American Winners. Blooms all summer to frost. Height 6-10\". (Ferry-Morse)","seedStart":"After frost, sow in open ground 1/4\" deep. For earlier bloom, start indoors 6-8 weeks before last frost. Germination 5-8 days. Thin/transplant when 2\". Harden off.","care":"Perfect for borders and containers. Easy to grow. Days to bloom: 45-60.","lowMaintenance":true},{"id":"zinnia-california-giants","name":"Zinnia - California Giants Mixed","emoji":"🌼","type":"flower","spacing":15,"daysToHarvest":47,"waterNeed":"low","sunNeed":"full","sowIndoors":-4,"transplantAfterFrost":1,"directSow":1,"harvestWeeks":14,"companions":["marigold","nasturtium","sunflower"],"enemies":[],"notes":"Large dahlia-type flowers in wide range of bright shades. Long summer bloom. Remove faded blooms to extend season. Height 24-36\". (Ferry-Morse)","seedStart":"After frost, sow in open ground 1/4\" deep. For earlier bloom, start indoors 4 weeks before. Germination 7-12 days. Thin/transplant at 3\".","care":"Deadhead regularly. Great for cut flower arrangements. Days to bloom: 35-60.","lowMaintenance":true},{"id":"zinnia-state-fair","name":"Zinnia - State Fair Giant Mixed","emoji":"🌼","type":"flower","spacing":12,"daysToHarvest":47,"waterNeed":"low","sunNeed":"full","sowIndoors":-4,"transplantAfterFrost":1,"directSow":1,"harvestWeeks":14,"companions":["marigold","nasturtium","sunflower"],"enemies":[],"notes":"Half-hardy annual. Huge 4-6\" blooms in luminous shades. Extremely vigorous. Height 2.5-4 ft. Many unique colors. (Ferry-Morse)","seedStart":"After frost, sow in open ground 1/4\" deep. For earlier bloom, start indoors 4 weeks before. Germination 5-10 days. Thin/transplant at 3\".","care":"Great for tall garden borders and cut flowers. Deadhead regularly. Days to bloom: 35-60.","lowMaintenance":true},{"id":"nasturtium-alaska","name":"Nasturtium - Alaska Mixed","emoji":"🌺","type":"flower","spacing":10,"daysToHarvest":36,"waterNeed":"low","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":1,"harvestWeeks":14,"companions":["tomato","cucumber","cabbage","radish","green-beans"],"enemies":[],"notes":"Bushy variety with green and white marbled leaves. Bright 2\" blooms in yellow, orange, crimson. Edible flowers and leaves with peppery watercress taste. Height 16-18\". (Ferry-Morse)","seedStart":"After frost, sow in open ground 1/2\" deep. Germination 7-14 days. Thin when 3\" tall. Does not transplant well.","care":"Water sparingly. Not too fertile soil — rich soil favors leaves over flowers. Edible in salads.","lowMaintenance":true},{"id":"nasturtium-tall-single","name":"Nasturtium - Tall Single Mixed","emoji":"🌺","type":"flower","spacing":10,"daysToHarvest":36,"waterNeed":"low","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":1,"harvestWeeks":14,"companions":["tomato","cucumber","cabbage","radish","green-beans"],"enemies":[],"notes":"Old-fashioned annual, climbs/sprawls. Fragrant flowers in sunny colors bloom until frost. Height up to 5 ft on support. Easy to grow. (Ferry-Morse)","seedStart":"Direct seed after frost. Plant 1/2\" deep in dry, well-drained location. Germination 8-12 days. Thin to 8-12\" apart.","care":"Rich soil favors leaves, not flowers. Water sparingly. Can seed in fall for winter bloom in mild climates.","lowMaintenance":true},{"id":"hollyhock-summer-carnival","name":"Hollyhock - Summer Carnival Mixed","emoji":"🌸","type":"flower","spacing":24,"daysToHarvest":100,"waterNeed":"medium","sunNeed":"full","sowIndoors":-7,"transplantAfterFrost":1,"directSow":1,"harvestWeeks":10,"companions":["marigold","zinnia","sunflower"],"enemies":[],"notes":"Stunning flowering biennial. Bright 4\" double blooms in pink, red, yellow. Lovely along fences and in cottage gardens. Reseeds annually. Height 4-6 ft. (Ferry-Morse)","seedStart":"Sow in open ground after frost, or start indoors 6-8 weeks before in sunny window. Plant 1/4\" deep. Germination 10-21 days. Transplant carefully.","care":"Stake in windy locations. Treat as biennial for best blooms. Days to bloom: ~100.","lowMaintenance":false},{"id":"wildflower-birds-butterfly","name":"Wildflower - Birds & Butterfly Mix","emoji":"🌼","type":"flower","spacing":6,"daysToHarvest":49,"waterNeed":"low","sunNeed":"full","sowIndoors":null,"transplantAfterFrost":null,"directSow":0,"harvestWeeks":20,"companions":[],"enemies":[],"notes":"Mix of annuals and perennials. Annuals bloom year 1, perennials year 2. Includes Centaurea, Calendula, Coreopsis, Delphinium, Dianthus, and more. Height 12-36\". (Ferry-Morse)","seedStart":"Broadcast thinly over prepared soil. Rake in lightly, no deeper than 1/8\". Soak area and maintain moisture 4-6 weeks. Germination 7-21 days.","care":"Ideal for meadows, sunny slopes, low-maintenance areas. Min 4 hrs sun daily. Drought resistant once established. Mix 1:2 sand to seed for even distribution. Days to bloom: 42-56.","lowMaintenance":true},{"id":"collard-greens","name":"Collard Greens","emoji":"🥬","type":"vegetable","spacing":18,"daysToHarvest":65,"waterNeed":"medium","sunNeed":"full","sowIndoors":-6,"transplantAfterFrost":-3,"directSow":-4,"harvestWeeks":30,"companions":["tomato","pepper","onion","dill","nasturtium","marigold","sweet-alyssum","calendula"],"enemies":["strawberry","fennel"],"notes":"Heat-tolerant brassica. Harvest outer leaves for continuous production. Sweeter after light frost.","seedStart":"Start indoors 6-8 weeks before last frost (early March). Plant 1/4\" deep. Transplant out 3 weeks before last frost when seedlings have 4 true leaves.","care":"Water 1-1.5\" per week. Mulch to retain moisture. Side-dress with compost monthly. Watch for cabbage worms — companion plant with nasturtium/marigold.","lowMaintenance":true},{"id":"butternut-squash","name":"Butternut Squash","emoji":"🌽","type":"vegetable","spacing":36,"daysToHarvest":110,"waterNeed":"medium","sunNeed":"full","sowIndoors":-3,"transplantAfterFrost":2,"directSow":1,"harvestWeeks":4,"companions":["nasturtium","green-beans","corn","marigold","oregano","borage","radish","sunflower"],"enemies":["potato","cucumber","cantaloupe"],"notes":"Stores 3-6 months in cool dry area. Cure 2 weeks in sun after harvest. Excellent food bank crop.","seedStart":"Start indoors 3-4 weeks before last frost (late March). Plant 1\" deep. Transplant 2 weeks after last frost when soil is 65°F+.","care":"Needs space — vines sprawl 8-12 ft. Water deeply at base, avoid wetting leaves. Hand-pollinate if few bees. Harvest when stem is dry and corky.","lowMaintenance":false},{"id":"sweet-alyssum","name":"Sweet Alyssum","emoji":"🌼","type":"flower","spacing":8,"daysToHarvest":50,"waterNeed":"low","sunNeed":"full","sowIndoors":-6,"transplantAfterFrost":-1,"directSow":-2,"harvestWeeks":20,"companions":["tomato","pepper","kale","collard-greens","broccoli","cabbage","lettuce","potato"],"enemies":[],"notes":"Living mulch & beneficial insect magnet. Low-growing carpet covers bare soil. Attracts hoverflies and parasitic wasps that eat aphids.","seedStart":"Start indoors 6 weeks before last frost (mid-March) or direct sow 2 weeks before last frost. Surface sow — needs light to germinate.","care":"Almost zero maintenance. Shear back by half if it gets leggy mid-summer — rebounds in 2 weeks. Self-seeds freely.","lowMaintenance":true},{"id":"calendula","name":"Calendula","emoji":"🌻","type":"flower","spacing":10,"daysToHarvest":45,"waterNeed":"low","sunNeed":"full","sowIndoors":-6,"transplantAfterFrost":-2,"directSow":-2,"harvestWeeks":16,"companions":["tomato","pepper","carrot","green-beans","strawberry","kale","cabbage","broccoli"],"enemies":[],"notes":"Edible flowers. Trap crop for aphids — protects neighboring veggies. Petals make tea or salve.","seedStart":"Start indoors 6 weeks before last frost or direct sow 2 weeks before last frost. Plant 1/4\" deep. Germinates best in cool soil.","care":"Deadhead regularly to extend bloom season. Tolerates light frost. Self-seeds prolifically — pull volunteers where unwanted.","lowMaintenance":true}];
const PLANT_BY_ID = Object.fromEntries(PLANTS.map(p=>[p.id,p]));
